using System;using System.IO;using System.Reflection;using UnityEngine;using Bokumyaku.Presentation;
public static class EnemyPoolCheck{
public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var flags=BindingFlags.Instance|BindingFlags.NonPublic;var w=(InkBattleWorld)typeof(BokumyakuGame).GetField("battleWorld",flags).GetValue(g);var root=(GameObject)typeof(InkBattleWorld).GetField("root",flags).GetValue(w);int before=root.GetComponentsInChildren<SpriteRenderer>(true).Length;for(int i=0;i<30;i++){w.Reset(g.Run);g.PresentBattle();}int after=root.GetComponentsInChildren<SpriteRenderer>(true).Length;if(before!=after)throw new Exception("Renderer count grew");var result=new{passed=true,cycles=30,before,after,method="Same artificial enemy fixture reset/render cycles; not allocation profiler or death soak"};File.WriteAllText(Path.GetFullPath("../docs/evidence/enemy-pool-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;}}
